import React, { useState } from "react";

export default function App() {
  const [disease, setDisease] = useState("");
  const [focus, setFocus] = useState("");
  const [location, setLocation] = useState("");
  const [whatIf, setWhatIf] = useState("");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleRun = async () => {
    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          disease: disease,
          intent: focus,
          location: location
        })
      });

      const result = await res.json();
      setData(result);

    } catch (err) {
      console.error(err);
      alert("Backend not connected");
    }

    setLoading(false);
  };

  return (
    <div style={{ display: "flex", height: "100vh", background: "#0B1220", color: "white" }}>

      {/* LEFT PANEL */}
      <div style={{ width: "260px", padding: "20px", borderRight: "1px solid #333" }}>
        <h2>Curalink X</h2>

        <input
          placeholder="Filter by disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          style={input}
        />

        <h3>Stats</h3>
        <p>Papers: {data?.publications?.length || 0}</p>
        <p>Trials: {data?.clinical_trials?.length || 0}</p>
      </div>

      {/* CENTER PANEL */}
      <div style={{ flex: 1, padding: "20px" }}>
        <h1>OpenAI reasoning copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={focus}
          onChange={(e) => setFocus(e.target.value)}
          style={textarea}
        />

        <button onClick={handleRun} style={button}>
          {loading ? "Running..." : "Send message"}
        </button>

        {/* STRUCTURED INPUTS */}
        <div style={{ marginTop: "20px" }}>
          <input placeholder="Location" value={location} onChange={(e)=>setLocation(e.target.value)} style={input} />
          <input placeholder="What-if treatment" value={whatIf} onChange={(e)=>setWhatIf(e.target.value)} style={input} />
        </div>

        {loading && <p>⏳ Running pipeline...</p>}
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: "400px", padding: "20px", borderLeft: "1px solid #333", overflowY: "auto" }}>

        {/* SUMMARY */}
        <div style={card}>
          <h3>Dynamic Insights</h3>
          {data ? <p>{data.summary}</p> : <p>No data yet</p>}
        </div>

        {/* PAPERS */}
        <div style={card}>
          <h3>Research papers</h3>
          {data?.publications?.map((p, i) => (
            <div key={i} style={item}>
              <strong>{p.title}</strong>
              <p style={meta}>{p.source} • {p.year}</p>
            </div>
          ))}
        </div>

        {/* TRIALS */}
        <div style={card}>
          <h3>Clinical trials</h3>
          {data?.clinical_trials?.map((t, i) => (
            <div key={i} style={item}>
              <strong>{t.title}</strong>
              <p style={meta}>{t.status}</p>
            </div>
          ))}
        </div>

      </div>
    </div>
  );
}

/* STYLES */
const input = {
  display: "block",
  width: "100%",
  padding: "10px",
  marginTop: "10px",
  background: "#111827",
  color: "white",
  border: "1px solid #333",
  borderRadius: "8px"
};

const textarea = {
  width: "100%",
  height: "100px",
  padding: "10px",
  marginTop: "10px",
  background: "#111827",
  color: "white",
  border: "1px solid #333",
  borderRadius: "8px"
};

const button = {
  marginTop: "10px",
  padding: "10px",
  width: "100%",
  background: "linear-gradient(90deg,#3b82f6,#8b5cf6)",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer"
};

const card = {
  background: "#111827",
  padding: "15px",
  marginTop: "15px",
  borderRadius: "10px"
};

const item = {
  borderTop: "1px solid #333",
  marginTop: "10px",
  paddingTop: "10px"
};

const meta = {
  fontSize: "12px",
  opacity: 0.7
};
